args.command:
cd /tmp/probe_cli && E=/workspace/executable
for w in sine square triangle sawtooth noise trapezium; do timeout 10 $E -n sy_$w.wav synth 0.01 $w 1000 2>/dev/null; done
python3 - <<'EOF'
import wave, struct
for w in ['sine','square','triangle','sawtooth','noise','trapezium']:
    try:
        f = wave.open(f'sy_{w}.wav'); n = f.getnframes(); sw=f.getsampwidth()
        data = f.readframes(n)
        if sw==2: vals = struct.unpack('<%dh'%(len(data)//2), data)
        elif sw==4: vals = struct.unpack('<%di'%(len(data)//4), data)
        print(w, 'rate', f.getframerate(), 'ch', f.getnchannels(), 'sw', sw, 'n', n, 'first12:', vals[:12])
    except Exception as e: print(w, 'ERR', e)
EOF
